  // ---- the match: generated by the engine (WebAssembly in a worker) and streamed in as replay data --------------
  // A match starts with its header (teams, conditions, mud map); then batches of frames, events and stats arrive and
  // are appended. The viewer plays what has arrived; a match that is not live is generated far ahead of the viewer
  // (about 30 times faster than real time), so it can be rewound and fast-forwarded; a live match stays about two
  // seconds ahead.
  var snd = new SVAudio.MatchSound(), soundOn = false, lastT = 0;
  snd.loadSamples("sounds/"); // the recorded crowd, net and woodwork (published next to the page)
  $("sound").addEventListener("click", function () {
    soundOn = !soundOn;
    if (soundOn) snd.enable(); else snd.disable();
    this.textContent = soundOn ? "Sound on" : "Sound off"; this.setAttribute("aria-pressed", String(soundOn));
  });
  var MODE = "staged", finished = false, resumeAt = null, token = 0, worker = null, workerReady = null, currentSeed = 0, lastProgress = 0;
  function engineError(msg) {
    note("The match engine could not start: " + msg + ". Open the page from its web address (not as a file) in a recent browser.");
    $("cbarText").textContent = "The match engine could not start";
  }
  function startWorker() {
    if (ONLINE === "guest") { worker = NET.remoteWorker; return Promise.resolve(); } // (the friend's match is played on the host's engine)
    if (workerReady) return workerReady;
    workerReady = new Promise(function (resolve, reject) {
      try { worker = new Worker(ENGINE_DIR + "worker.js", { type: "module" }); } catch (e) { reject(e); return; }
      worker.onerror = function (e) { reject(new Error(e.message || "worker failed")); };
      worker.onmessage = function (ev) {
        var m = ev.data;
        if (m.type === "ready") resolve();
        else if (m.type === "error") { engineError(m.message); reject(new Error(m.message)); }
        else if (m.token !== token) return; // a match that was dropped
        else if (m.type === "header") { beginMatch(JSON.parse(m.header)); NET.forward(m); }
        else if (m.type === "chunk") { NET.forward(m); appendChunk(m); }
      };
      worker.postMessage({ cmd: "init", base: new URL(ENGINE_DIR, location.href).href });
    });
    workerReady.catch(function (e) { workerReady = null; engineError(e.message); });
    return workerReady;
  }
  // What the engine plays in: rain, snow, a worn pitch and wind change the football; sunny / cloudy and day / night do not.
  function engineSettings(seed) {
    return { weather: SET.weather, maintenance: SET.maint === "2" ? 1 : SET.maint === "1" ? .5 : 0, wind: SET.wind === "1" ? 12 : 0, windAngle: (seed * 97 % 360) * Math.PI / 180, night: !!SET.night };
  }
  // "Start match" works only once the engine has sent the match (beginMatch). Until then it says so and cannot be
  // pressed - a press before that used to be dropped without a word.
  function kickoffReady(ready, failed) {
    var b = $("kickoff");
    if (!ready && !b.disabled) b.dataset.label = b.textContent;
    b.disabled = !ready; b.setAttribute("aria-busy", String(!ready && !failed));
    b.textContent = ready ? (b.dataset.label || "Start match") : failed ? "The match engine did not load - reload the page" : "Preparing the match...";
  }
  function startMatch(mode, seed, resumeRel) {
    MODE = mode; currentSeed = seed; token++; var mine = token;
    LIVE_T = 0; setRewound(false);
    KICKED = mode !== "live"; PENDING = []; SEL = null;
    if (mode === "live" && USER_PLAN) { PLAN = USER_PLAN; TAC = USER_TAC; } // (your own team - not the one a random match showed)
    $("prematch").hidden = mode !== "live";
    if (mode === "live") kickoffReady(false);
    document.body.classList.toggle("live", mode === "live");
    document.querySelectorAll(".modes button").forEach(function (b) { b.setAttribute("aria-pressed", String(b.getAttribute("data-mode") === mode)); });
    if (mode === "live") { speed = 1; document.querySelectorAll("[data-speed]").forEach(function (o) { o.setAttribute("aria-pressed", String(o.getAttribute("data-speed") === "1")); }); }
    resumeAt = resumeRel === undefined ? null : resumeRel;
    note("Starting the match engine...");
    startWorker().then(function () {
      if (mine !== token) return;
      var c = engineSettings(seed);
      worker.postMessage({ cmd: "stop", token: mine });
      worker.postMessage({ cmd: "start", token: mine, mode: ONLINE === "host" ? "online" : mode, seed: seed, weather: c.weather, maintenance: c.maintenance, wind: c.wind, windAngle: c.windAngle, night: c.night, competition: SET.comp || "League", homeStrength: ONLINE ? "medium" : SET.hstr || "medium", awayStrength: ONLINE ? "medium" : SET.astr || "medium", lead: mode === "live" ? 20 : 0, plan: planString(), hold: mode === "live" });
    }, function () { if (mine === token && mode === "live") kickoffReady(false, true); });
  }
